#!/usr/bin/env bash
# Shares one Flowloom webhook credential (HMAC signing secret or header token)
# with a customer WITHOUT the value ever passing through chat, email or this
# terminal: it asks OpenBao for a response-WRAPPED copy, a single-use token
# that expires after TTL and can be redeemed exactly once.
#
# The credential itself was generated by the Flowloom engine of that
# environment on the webhook's first deploy and written to
#   secret/flowloom/<tenant>/<env>/_webhooks/<process_id>/<element_id>
# (see Flowloom's docs/PROMOTION.md, "Credentials for customers").
#
# Usage:
#   bash scripts/flowloom-webhook-secret-share.sh <env> <process_id> <element_id> [ttl] [tenant]
#   e.g. bash scripts/flowloom-webhook-secret-share.sh prod 01a136c5-a548-7b7f-a3e5-9da41cc31ed1 StartEvent_1 24h
#
# Prints only the wrapping token (safe to send: single-use, short-lived) and
# the command the customer runs to redeem it. If someone else redeems it
# first, the customer's redeem fails: rotate the credential in that case.
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
source "${repo_root}/scripts/lib/script-guide.sh"

env_slug="${1:-}"
process_id="${2:-}"
element_id="${3:-}"
ttl="${4:-}"
tenant="${5:-}"

script_guide <<'GUIDE'
Flowloom: share a webhook credential with a customer (single-use token)
------------------------------------------------------------------------
Usage:  bash scripts/flowloom-webhook-secret-share.sh [env] [process_id] [element_id] [ttl] [tenant]
        (anything left out is asked for below)

  env         dev | staging | prod: the engine whose webhook it is
  process_id  the process design's UUID (Studio: webhook panel / Process info)
  element_id  the webhook StartEvent's id, e.g. StartEvent_1
  ttl         how long the share token stays valid, e.g. 30m or 24h (default 24h)
  tenant      tenant slug (default miak-it)

What it does: asks OpenBao for a response-WRAPPED copy of the credential and
prints only that single-use token plus the curl command the customer runs to
redeem it. The credential itself never appears here. If someone else redeems
the token first, the customer's redeem fails: rotate the credential then.

It will ask for: missing values, then your OpenBao admin login.
GUIDE

ask_value env_slug "Environment (dev/staging/prod)" "prod" '^[a-z0-9-]+$'
ask_value process_id "Process id (UUID)" "" '^[0-9a-f-]{36}$'
ask_value element_id "Webhook element id" "StartEvent_1" '^[A-Za-z0-9_.-]+$'
ask_value ttl "Share token lifetime" "24h" '^[0-9]+[smh]$'
ask_value tenant "Tenant" "miak-it" '^[a-z0-9-]+$'

kubeconfig="${repo_root}/kubeconfig"
namespace="openbao"
pod="openbao-0"
openbao_addr="https://openbao.miak-it.com"
path="secret/flowloom/${tenant}/${env_slug}/_webhooks/${process_id}/${element_id}"

source "${repo_root}/scripts/lib/openbao-login.sh"
openbao_login_admin

wrap_token="$(
  kubectl --kubeconfig "${kubeconfig}" -n "${namespace}" exec "${pod}" -- \
    env "BAO_TOKEN=${BAO_TOKEN}" bao kv get -wrap-ttl="${ttl}" -field=wrapping_token "${path}" 2>/dev/null ||
    kubectl --kubeconfig "${kubeconfig}" -n "${namespace}" exec "${pod}" -- \
      env "BAO_TOKEN=${BAO_TOKEN}" sh -lc "bao kv get -wrap-ttl='${ttl}' -format=json '${path}' | sed -n 's/.*\"token\": *\"\\([^\"]*\\)\".*/\\1/p' | head -1"
)"

if [ -z "${wrap_token}" ]; then
  echo "No credential found at ${path} (not deployed with HMAC/token auth yet?)" >&2
  exit 1
fi

cat <<EOF
Single-use share token for ${env_slug} webhook ${element_id} (expires in ${ttl}):

  ${wrap_token}

Send that token to the customer with these instructions. They run, once:

  curl -s -X POST ${openbao_addr}/v1/sys/wrapping/unwrap -H "X-Vault-Token: ${wrap_token}"

The response's "data" holds the credential: "secret" (HMAC signing secret) plus
"signature_header", or "token" plus "header". The integration guide for this
webhook explains how to use it. The share token stops working after one use.
EOF

unset wrap_token
